/**
 * M00 supplementary tests: rs-canon/1 canonical encoding and digest test vectors.
 * Vectors are hand-derived from the byte layout in src/canonical/encoding.ts, not generated by it.
 */
import { createHash } from 'node:crypto';
import fc from 'fast-check';
import { describe, expect, it } from 'vitest';
import { canonicalEncode, canonicalJson, digestValue, isRouteSpecError, toHex } from '../src/index.ts';
import { reverseKeyOrder } from './fixtures.ts';

const HAND_VECTORS: Array<[string, unknown, string]> = [
  ['null', null, '00'],
  ['false', false, '01'],
  ['true', true, '02'],
  ['zero', 0, '030000000130'],
  ['negative zero is zero', -0, '030000000130'],
  ['negative integer', -42, '03000000032d3432'],
  ['bigint 2^64', 2n ** 64n, '0300000014' + Buffer.from('18446744073709551616').toString('hex')],
  ['ascii string', 'a', '040000000161'],
  ['two-byte utf-8', 'é', '0400000002c3a9'],
  ['empty array', [], '0600000000'],
  ['empty object', {}, '0700000000'],
  ['bytes', Uint8Array.of(1, 2), '05000000020102'],
  ['object keys sorted', { b: 1, a: true }, '07000000020400000001610204000000016203000000013' + '1'],
  ['nested array', [null, [true]], '060000000200060000000102'],
  // UTF-8 byte order differs from UTF-16 code-unit order for these keys.
  [
    'utf-8 key order',
    { '\u{1F600}': 1, '｡': 2 },
    '0700000002' + '0400000003efbda1' + '030000000132' + '0400000004f09f9880' + '030000000131',
  ],
];

describe('rs-canon/1 encoding vectors', () => {
  for (const [name, value, hex] of HAND_VECTORS) {
    it(`encodes ${name}`, () => {
      expect(toHex(canonicalEncode(value))).toBe(hex);
    });
  }

  it('encodes non-integer numbers only when explicitly allowed', () => {
    expect(toHex(canonicalEncode(1.5, { allowNonIntegerNumbers: true }))).toBe('0800000003312e35');
    expect(() => canonicalEncode(1.5)).toThrow(/Non-integer/);
  });

  it('digests with the pinned domain-separated SHA-256 construction', () => {
    const value = { amount: '1000000', epoch: 3 };
    const expected = createHash('sha256')
      .update(Buffer.from('rs-canon/1\u0000routespec.test/1\u0000', 'utf8'))
      .update(canonicalEncode(value))
      .digest('hex');
    expect(digestValue('routespec.test/1', value)).toBe(`sha256:${expected}`);
    expect(digestValue('routespec.test/2', value)).not.toBe(`sha256:${expected}`);
  });

  it('rejects values whose encoding would depend on platform or runtime', () => {
    const cases: unknown[] = [
      undefined,
      { a: undefined },
      new Date(0),
      new Map([['a', 1]]),
      new Set([1]),
      () => 1,
      Symbol('x'),
      Number.NaN,
      Number.POSITIVE_INFINITY,
      2 ** 60,
      '\ud800',
      // eslint-disable-next-line no-sparse-arrays
      [1, , 3],
      new (class Custom {})(),
    ];
    for (const value of cases) {
      let caught: unknown;
      try {
        canonicalEncode(value);
      } catch (error) {
        caught = error;
      }
      expect(isRouteSpecError(caught), `value ${String(typeof value)} must be rejected`).toBe(true);
    }
  });

  it('enforces depth and size limits', () => {
    let deep: unknown = null;
    for (let i = 0; i < 70; i++) deep = [deep];
    expect(() => canonicalEncode(deep)).toThrow(/depth/);
    expect(() => canonicalEncode('x'.repeat(100), { maxBytes: 50 })).toThrow(/byte limit/);
  });

  it('is invariant to object key insertion order (property)', () => {
    fc.assert(
      fc.property(fc.jsonValue({ maxDepth: 4 }), (value) => {
        let encodable = true;
        try {
          canonicalEncode(value, { allowNonIntegerNumbers: true });
        } catch {
          encodable = false; // e.g. -0 inside floats or non-safe integers
        }
        fc.pre(encodable);
        const a = toHex(canonicalEncode(value, { allowNonIntegerNumbers: true }));
        const b = toHex(canonicalEncode(reverseKeyOrder(value), { allowNonIntegerNumbers: true }));
        return a === b;
      }),
      { numRuns: 300 },
    );
  });

  it('canonical JSON sorts keys and refuses inexact bigint JSON', () => {
    expect(canonicalJson({ b: [2, 1], a: 'x' })).toBe('{"a":"x","b":[2,1]}');
    expect(() => canonicalJson({ n: 1n })).toThrow();
  });
});
